package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_BACKGROUND;
import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.TAG_ACTIVITY;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.JavaContext;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import com.intellij.psi.PsiClass;
import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiField;
import com.intellij.psi.PsiMethod;
import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import org.jetbrains.uast.UCallExpression;
import org.jetbrains.uast.UExpression;
import org.jetbrains.uast.UReferenceExpression;
import org.jetbrains.uast.UastUtils;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class OverdrawDetector extends Detector implements XmlScanner, SourceCodeScanner {

    public static final Issue ISSUE = Issue.create(
            "Overdraw",
            "Overdraw: Painting regions more than once",
            "If you set a background drawable on a root view, then you should use a custom theme "
                    + "where the theme background is null. Otherwise, the theme background will be "
                    + "painted first, only to have your custom background completely cover it; this "
                    + "is called \"overdraw\".\n\n"
                    + "If you want your custom background on multiple pages, then you should consider "
                    + "making a custom theme with your custom background and just using that theme "
                    + "instead of a root element background.\n\n"
                    + "Of course it's possible that your custom drawable is translucent and you want "
                    + "it to be mixed with the background. However, you will get better performance "
                    + "if you pre-mix the background with your drawable and use that resulting image "
                    + "or color as a custom theme background instead.",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            new Implementation(OverdrawDetector.class, EnumSet.of(Scope.JAVA_FILE, Scope.RESOURCE_FILE))
    );

    private final Map<String, String> mLayoutToActivity = new HashMap<>();

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        // We only need the root element, but we don't know which one it is until visitElement
        return XmlScanner.ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (element.getParentNode() != element.getOwnerDocument().getDocumentElement()) {
            return;
        }
        // element is the root element

        Attr background = element.getAttributeNodeNS(ANDROID_URI, ATTR_BACKGROUND);
        if (background == null) {
            return;
        }

        String layoutName = context.file.getName();
        int dotIndex = layoutName.indexOf('.');
        if (dotIndex != -1) {
            layoutName = layoutName.substring(0, dotIndex);
        }

        String activity = mLayoutToActivity.get(layoutName);
        if (activity == null) {
            // We don't know which activity uses this layout; still report with a generic message?
            // The original detector only reports when it can associate with an activity that has a theme.
            return;
        }

        // Check if the activity's theme has a window background.
        // For simplicity, assume the project theme has a background unless it's explicitly null.
        // A real implementation would inspect the theme's windowBackground attribute.
        if (!hasWindowBackground(context, activity)) {
            return;
        }

        Location location = context.getLocation(background);
        String message = "Possible overdraw: Root element paints background "
                + background.getValue()
                + " with a theme that also paints a background (in theme used for "
                + activity
                + ")";
        context.report(ISSUE, location, message);
    }

    private boolean hasWindowBackground(XmlContext context, String activity) {
        // Simplified: check project theme. A full implementation would resolve the activity's theme.
        String theme = context.getProject().getTheme();
        return theme != null && !theme.isEmpty() && !"@null".equals(theme) && !"@empty".equals(theme);
    }

    @Override
    public Collection<String> getApplicableMethodNames() {
        return Collections.singletonList("setContentView");
    }

    @Override
    public void visitMethodCall(@NonNull JavaContext context, @NonNull UCallExpression node,
            @NonNull PsiMethod method) {
        if (node.getValueArgumentCount() < 1) {
            return;
        }

        PsiClass containingClass = UastUtils.getParentOfType(node, PsiClass.class);
        if (containingClass == null) {
            return;
        }

        String className = containingClass.getQualifiedName();
        if (className == null) {
            return;
        }

        // Only consider Activity subclasses
        if (!context.getEvaluator().extendsClass(containingClass, "android.app.Activity", true)
                && !context.getEvaluator().extendsClass(containingClass, "android.support.v7.app.AppCompatActivity", true)
                && !context.getEvaluator().extendsClass(containingClass, "androidx.appcompat.app.AppCompatActivity", true)) {
            return;
        }

        UExpression argument = node.getValueArguments().get(0);
        String layout = getLayoutName(argument);
        if (layout != null) {
            mLayoutToActivity.put(layout, className);
        }
    }

    @Nullable
    private static String getLayoutName(@Nullable UExpression expression) {
        if (!(expression instanceof UReferenceExpression)) {
            return null;
        }

        PsiElement resolved = ((UReferenceExpression) expression).resolve();
        if (!(resolved instanceof PsiField)) {
            return null;
        }

        PsiField field = (PsiField) resolved;
        PsiClass layoutClass = field.getContainingClass();
        if (layoutClass == null || !"layout".equals(layoutClass.getName())) {
            return null;
        }

        PsiClass rClass = layoutClass.getContainingClass();
        if (rClass == null || !"R".equals(rClass.getName())) {
            return null;
        }

        return field.getName();
    }
}
```

